import {equipmentSlots,moveSlots,pickerPanel,pickerAction} from './slot-pickers.mjs';
import {equipmentPanel} from './equipment-ui.mjs';
import {heldItems,equip,unequip} from './model.mjs';
import {profile,level,stats,NATURES,STAT_NAMES,candy,setEV,evCost,trainIV,setNature,setAbility,abilityItem,equippedMoves,setMoves} from './training.mjs';
import {materials,MATERIALS} from './resources.mjs';
import * as Art from './art.mjs';
const TABS=[['stats','Statistiques'],['equipment','Objets'],['moves','Capacités'],['traits','Nature & talent'],['level','Niveau & évolution'],['iv','IV & capsules']];
export class PokemonLab {
 constructor(g){this.g=g;this.tab='stats'}
 open(key){const g=this.g;if(!g.dex[parseInt(key)]||key.endsWith('s')&&!g.poke(key).shiny)return;const owned=g.state.roster.includes(key);if(parseInt(this.key)!==parseInt(key))this.tab='stats';if(this.key!==key)this.picker=null;this.key=key;const d=g.poke(key),p=owned?profile(g.state,key):null,L=owned?level(p):0,nature=owned?NATURES.find(n=>n.id===p.nature):null,s=owned?stats(g.dex,key,p):null;materials(g.state);
 g.openModal(`<div class="pokemon-detail-sheet"><aside class="sheet-portrait"><span class="eyebrow">${owned?'TON COMPAGNON':'À DÉCOUVRIR'}</span>${this.variantPicker(key)}<canvas id="lab-portrait" width="240" height="230" aria-label="${g.escape(d.name)} en pixel art"></canvas><span class="rarity-tag ${d.rarity}">${g.rarity(d.rarity).name}${key.endsWith('s')?' · CHROMATIQUE':''}</span><h2>${d.name}</h2><b>${owned?'Niveau '+L:'Non obtenu'}</b><p>${d.types.map(t=>Art.TYPE_NAMES[t]).join(' · ')}</p>${owned?`<div class="portrait-facts"><span>Nature <strong>${nature.name}</strong></span><span>Talent <strong>${d.abilities?.[p.ability]?.name||'Standard'}</strong></span><span>Objets ${heldItems(g.state,key).length}/3 <strong>${g.held(key).name||'Aucun'}</strong></span></div>`:``}${owned&&d.rarity==='legendary'?`<button class="legendary-replay" data-act="legendary-replay" data-key="${key}">Revoir sa rencontre légendaire ↗</button>`:''}</aside><div class="sheet-details"><nav class="sheet-tabs" aria-label="Amélioration du Pokémon">${TABS.map(([id,label])=>`<button data-act="lab-tab" data-tab="${id}" class="${this.tab===id?'active':''}">${label}</button>`).join('')}</nav><div class="sheet-panel">${owned?(this.picker?pickerPanel(this):this.panel(d,p,L,s)):this.lockedPanel(key)}</div><div class="sheet-resources"><span>✦ <b>${g.state.coins.toLocaleString('fr')}</b> poussières d’étoiles</span><button class="text-button" data-act="lab-bag">Voir mon sac →</button></div></div></div>`,{className:'pokemon-dialog'});
 const search=g.modal.querySelector('[data-move-search]');if(search)search.addEventListener('input',()=>{const pos=search.selectionStart;this.picker.query=search.value;clearTimeout(this.searchTimer);this.searchTimer=setTimeout(()=>{this.open(key);const next=g.modal.querySelector('[data-move-search]');next?.focus();next?.setSelectionRange(pos,pos)},180)});
 const canvas=g.modal.querySelector('#lab-portrait'),ctx=canvas.getContext('2d');Art.preload([key]);const draw=t=>{if(!canvas.isConnected||!g.modal.open)return;ctx.clearRect(0,0,240,230);Art.drawPortrait(ctx,key,120,115,205,'Idle',0,g.state.settings.reducedMotion?0:t/1000);requestAnimationFrame(draw)};requestAnimationFrame(draw);
 g.modal.querySelectorAll('[data-ev-input]').forEach(input=>input.addEventListener('input',()=>{const i=+input.dataset.evInput,n=+input.value;g.modal.querySelector('#ev-number-'+i).value=n;const draft={...p,ev:p.ev.map((v,j)=>i===j?n:v)};g.modal.querySelector('#stat-preview-'+i).textContent=stats(g.dex,key,draft)[i];const button=g.modal.querySelector('#ev-apply-'+i),cost=evCost(p.ev[i],n);button.textContent=cost?`Appliquer · ${cost} ✦`:'Appliquer gratuitement';button.disabled=n===p.ev[i]||g.state.coins<cost}));
 g.modal.querySelectorAll('[data-ev-number]').forEach(input=>input.addEventListener('input',()=>{const range=g.modal.querySelector('#ev-range-'+input.dataset.evNumber);range.value=Math.max(0,Math.min(+range.max,+input.value||0));range.dispatchEvent(new Event('input'))}));
 const ability=g.modal.querySelector('#lab-ability');if(ability)ability.addEventListener('change',()=>{const item=abilityItem(d,p,+ability.value),m=MATERIALS.find(m=>m.key===item),button=g.modal.querySelector('[data-act="train-ability"]');button.textContent=`Utiliser 1 ${m.name}`;button.disabled=p.ability===+ability.value||g.state.materials[item]<1});
 const selects=[...g.modal.querySelectorAll('[data-move-select]')];for(const select of selects)select.addEventListener('change',()=>{const old=equippedMoves(d,p),cost=selects.filter((e,i)=>+e.value!==old[i].id).length,button=g.modal.querySelector('[data-act="train-moves"]');button.textContent=`Enregistrer · ${cost} écaille${cost>1?'s':''} cœur`;button.disabled=!cost||g.state.materials.heartScale<cost});
 }

 variantPicker(key){const g=this.g,d=g.poke(key);if(!d.shiny)return '';const id=String(d.id);return `<div class="variant-picker" role="group" aria-label="Apparence de ${g.escape(d.name)}">${[[id,'Normal'],[id+'s','✧ Chromatique']].map(([k,label])=>`<button data-act="lab-variant" data-key="${k}" aria-pressed="${k===key}" class="${k===key?'selected':''}"><b>${label}</b><small>${g.state.roster.includes(k)?'Obtenu':'Aperçu · non obtenu'}</small></button>`).join('')}</div>`}
 lockedPanel(key){return `<div class="variant-locked"><span class="eyebrow">${key.endsWith('s')?'APPARENCE CHROMATIQUE':'APPARENCE NORMALE'}</span><h3>Une rencontre à venir</h3><p>Tu n’as pas encore obtenu cette variante. Tu peux admirer son apparence ici ; ses améliorations seront disponibles une fois obtenue.</p><button class="primary" data-act="lab-variant-invoke">Voir les portails ↗</button></div>`}
 panel(d,p,L,s){const g=this.g,bag=g.state.materials;if(this.tab==='equipment')return equipmentSlots(g,this.key);
 if(this.tab==='stats'){const total=p.ev.reduce((a,b)=>a+b,0);return `<header><span class="eyebrow">POUSSIÈRE D’ÉTOILES</span><h3>Façonne ses statistiques</h3><p>Ajuste les curseurs puis applique. 1 EV coûte 10 poussières ; réduire une valeur est gratuit, sans remboursement.</p></header><div class="ev-budget"><b>${total} / 510 EV</b><span>252 maximum par statistique</span></div><div class="stat-controls">${STAT_NAMES.map((name,i)=>`<div class="stat-control"><div><b>${name}</b><strong id="stat-preview-${i}">${s[i]}</strong></div><div class="stat-slider"><input id="ev-range-${i}" data-ev-input="${i}" type="range" min="0" max="${Math.min(252,510-total+p.ev[i])}" step="1" value="${p.ev[i]}" aria-label="EV ${name}"><label><input id="ev-number-${i}" data-ev-number="${i}" type="number" min="0" max="252" value="${p.ev[i]}" aria-label="Valeur EV ${name}"> EV</label></div><button id="ev-apply-${i}" data-act="train-ev" data-index="${i}" disabled>Appliquer</button></div>`).join('')}</div>`}
 if(this.tab==='moves')return moveSlots(g,this.key);
 if(this.tab==='traits')return `<header><span class="eyebrow">OBJETS D’EXPLORATION</span><h3>Nature & talent</h3><p>Les aromates, pilules et patchs se trouvent dans les coffres de survie.</p></header><section class="trait-editor"><div><img class="material-icon" src="assets/materials/adamant-mint.png" alt=""><h4>Nature</h4><p>Un aromate permet de choisir sa nature et son influence sur les statistiques.</p><select id="lab-nature" aria-label="Nature">${NATURES.map(n=>`<option value="${n.id}" ${n.id===p.nature?'selected':''}>${n.name}${n.up>=0?' · +'+STAT_NAMES[n.up]+' / −'+STAT_NAMES[n.down]:' · Neutre'}</option>`).join('')}</select><button data-act="train-nature" ${bag.mint<1?'disabled':''}>Utiliser 1 aromate</button><small>${bag.mint} aromates dans ton sac</small></div><div><img class="material-icon" src="assets/materials/ability-capsule.png" alt=""><h4>Talent</h4><p>Pilule pour un talent classique ; patch pour accéder au talent caché ou en revenir.</p><select id="lab-ability" aria-label="Talent">${(d.abilities||[]).map((a,i)=>`<option value="${i}" ${i===p.ability?'selected':''}>${a.name}${a.hidden?' · Caché':''}</option>`).join('')}</select><button data-act="train-ability" disabled>Choisis un autre talent</button><small>${bag.abilityPill} pilules · ${bag.abilityPatch} patchs</small></div></section><p class="sheet-note">Les talents disponibles sont ceux de cette espèce. Les effets pris en charge sont détaillés dans les règles du jeu.</p>`;
 if(this.tab==='iv')return `<header><span class="eyebrow">ENTRAÎNEMENT ULTIME</span><h3>Des IV au maximum</h3><p>Capsule d’argent : un IV à 31. Capsule d’or : les six IV à 31.</p></header>${L<100?'<div class="level-lock">🔒 Débloqué au niveau 100<br><small>Continue de gagner de l’XP ou utilise des bonbons.</small></div>':''}<div class="iv-grid">${STAT_NAMES.map((name,i)=>`<div><b>${name}</b><strong>${p.iv[i]}<small> / 31</small></strong><button data-act="train-iv" data-index="${i}" ${L!==100||bag.silverCap<1||p.iv[i]===31?'disabled':''}>1 capsule d’argent</button></div>`).join('')}</div><button class="primary" data-act="train-gold" ${L!==100||bag.goldCap<1||p.iv.every(v=>v===31)?'disabled':''}>Maximiser les six IV · 1 capsule d’or</button><p class="sheet-note">${bag.silverCap} capsules d’argent · ${bag.goldCap} capsules d’or</p>`;
 return `<header><span class="eyebrow">NIVEAU ${L} / 100</span><h3>Grandir ensemble</h3><p>Les mini-jeux accordent de l’expérience. Chaque bonbon apporte 100 XP.</p></header><section class="sheet-level"><strong>${L}</strong><div><b>${p.xp.toLocaleString('fr')} XP ${L<100?' / '+((L+1)**3).toLocaleString('fr'):' · MAX'}</b><i><em style="width:${L===100?100:(p.xp-L**3)/((L+1)**3-L**3)*100}%"></em></i><small>${g.state.candies} bonbons disponibles</small></div></section><div class="candy-actions"><button class="primary" data-act="train-candy" data-count="1" ${L===100||g.state.candies<1?'disabled':''}>1 bonbon · +100 XP</button><button data-act="train-candy" data-count="10" ${L===100||g.state.candies<10?'disabled':''}>10 bonbons · +1 000 XP</button></div><section class="sheet-evolution">${g.evolutions.panel(this.key)}</section>`;
 }
 action(kind,d){const g=this.g;if(kind==='lab-variant'){const key=String(d.key);if(parseInt(key)!==parseInt(this.key)||key.endsWith('s')&&!g.poke(key).shiny)return;if(g.state.roster.includes(key)){g.state.pokemonVariants||={};g.state.pokemonVariants[parseInt(key)]=key.endsWith('s')?'shiny':'normal';g.save();if(!g.mode)g.render()}this.open(key);return}if(kind==='lab-variant-invoke'){g.summoning.gen=g.poke(this.key).gen;g.closeModal(true);g.route('gacha');return}if(pickerAction(this,kind,d))return;if(kind==='lab-equipment'){this.key=d.key;this.picker=null;this.tab='equipment';this.open(d.key);return}const key=this.key;if(kind==='lab-equip'||kind==='lab-unequip'){const ok=kind==='lab-equip'?equip(g.state,g.modal.querySelector('#lab-equip-item').value,key):unequip(g.state,key,d.uid);if(ok){g.save();g.render();this.open(key)}else g.toast('Choisis un objet différent, avec un emplacement disponible.');return}if(kind==='lab-bag'){g.closeModal();g.route('inventory');return}if(kind==='lab-tab'){this.picker=null;if(TABS.some(([id])=>id===d.tab))this.tab=d.tab;this.open(key);return}if(!g.state.roster.includes(key))return;let ok=false;if(kind==='train-candy')ok=candy(g.state,key,+d.count);if(kind==='train-ev')ok=setEV(g.state,key,+d.index,+g.modal.querySelector('#ev-range-'+d.index).value);if(kind==='train-iv')ok=trainIV(g.state,key,+d.index);if(kind==='train-gold')ok=trainIV(g.state,key,0,true);if(kind==='train-nature')ok=setNature(g.state,key,g.modal.querySelector('#lab-nature').value);if(kind==='train-ability')ok=setAbility(g.dex,g.state,key,+g.modal.querySelector('#lab-ability').value);if(kind==='train-moves')ok=setMoves(g.dex,g.state,key,[0,1,2,3].map(i=>+g.modal.querySelector('#lab-move-'+i).value));if(kind==='train-evolve'){const index=(g.poke(key).evolutions||[]).findIndex(e=>e.id===+d.id);if(index>=0)g.evolutions.start(key,index);return}if(ok){g.save();g.render();this.open(this.key);g.audio.tone(550,.07);if(kind==='train-candy'&&g.state.evolutionChecks.includes(key)){g.closeModal(true);g.evolutions.pump();if(!g.modal.open)this.open(key)}}else g.toast('Vérifie le niveau, les objets disponibles et les limites de statistiques. Les capacités doivent être débloquées et différentes.')}
}
